// IMPORTANT: All Insert/Update types are defined as FLAT objects.
// Do NOT use Omit<Database['public']['Tables'][...]['Row']>
// inside this file — that creates self-referential types which
// TypeScript may resolve to `never` in complex generic contexts.
// ============================================================

export type Json =
  | string
  | number
  | boolean
  | null
  | { [key: string]: Json | undefined }
  | Json[];

// ─── Enum types (must match Prisma schema enums) ─────────────

export type UserRole      = 'SUPER_ADMIN' | 'ADMIN' | 'MANAGER' | 'STAFF';
export type TripStatus    = 'DRAFT' | 'QUOTATION' | 'CONFIRMED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
export type LeadStatus    = 'NEW' | 'CONTACTED' | 'FOLLOW_UP' | 'QUOTATION_SENT' | 'CONFIRMED' | 'CONVERTED' | 'CANCELLED';
export type LeadPriority  = 'LOW' | 'MEDIUM' | 'HIGH';
export type BookingType   = 'FLIGHT' | 'HOTEL' | 'TRAIN' | 'BUS' | 'CAB' | 'VISA' | 'INSURANCE' | 'ACTIVITY' | 'OTHER';
export type BookingStatus = 'PENDING' | 'CONFIRMED' | 'ISSUED' | 'SUBMITTED' | 'APPROVED' | 'REJECTED' | 'CHECKED_IN' | 'DEPARTED' | 'COMPLETED' | 'CANCELLED';
export type PaymentStatus = 'PENDING' | 'RECEIVED' | 'PAID' | 'FAILED' | 'REFUNDED';
export type TaskPriority  = 'LOW' | 'MEDIUM' | 'HIGH' | 'URGENT';
export type TaskStatus    = 'PENDING' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
export type DocumentCategory = 'PASSPORT' | 'VISA' | 'INSURANCE' | 'FLIGHT_TICKET' | 'HOTEL_VOUCHER' | 'PAN_CARD' | 'AADHAAR' | 'OTHER';

