// ─── Update types ─────────────────────────────────────────────

export type OrgUpdate             = Partial<OrgInsert>;
export type ProfileUpdate         = Partial<ProfileInsert>;
export type CustomerUpdate        = Partial<CustomerInsert>;
export type LeadUpdate            = Partial<LeadInsert>;
export type TripUpdate            = Partial<TripInsert>;
export type BookingUpdate         = Partial<BookingInsert>;
export type CustomerPaymentUpdate = Partial<CustomerPaymentInsert>;
export type SupplierPaymentUpdate = Partial<SupplierPaymentInsert>;
export type TaskUpdate            = Partial<TaskInsert>;
// Activity logs and timeline are immutable — no Update type needed.
export type DocumentUpdate        = Partial<DocumentInsert>;

// ─── Database interface ───────────────────────────────────────
// IMPORTANT: GenericTable (from @supabase/supabase-js) requires
//   Relationships: GenericRelationship[]
// Each table must include this field or the Supabase client resolves
// all Insert/Row types to `never` via a failing conditional type check.
// We use `never[]` because `never extends GenericRelationship` (subtype of all types),
// so `never[]` IS assignable to `GenericRelationship[]` (covariant array).
// Do NOT use `readonly []` (`as const` on an array) — it is NOT assignable
// to a mutable array type and will cause the same `never` failure.

export interface Database {
  public: {
    Tables: {
      organisations:     { Row: OrgRow;            Insert: OrgInsert;            Update: OrgUpdate;            Relationships: never[] };
      profiles:          { Row: ProfileRow;         Insert: ProfileInsert;         Update: ProfileUpdate;         Relationships: never[] };
      customers:         { Row: CustomerRow;        Insert: CustomerInsert;        Update: CustomerUpdate;        Relationships: never[] };
      leads:             { Row: LeadRow;            Insert: LeadInsert;            Update: LeadUpdate;            Relationships: never[] };
      trips:             { Row: TripRow;            Insert: TripInsert;            Update: TripUpdate;            Relationships: never[] };
      bookings:          { Row: BookingRow;         Insert: BookingInsert;         Update: BookingUpdate;         Relationships: never[] };
      customer_payments: { Row: CustomerPaymentRow; Insert: CustomerPaymentInsert; Update: CustomerPaymentUpdate; Relationships: never[] };
      supplier_payments: { Row: SupplierPaymentRow; Insert: SupplierPaymentInsert; Update: SupplierPaymentUpdate; Relationships: never[] };
      tasks:             { Row: TaskRow;            Insert: TaskInsert;            Update: TaskUpdate;            Relationships: never[] };
      activity_logs:     { Row: ActivityLogRow;     Insert: ActivityLogInsert;     Update: Partial<ActivityLogInsert>; Relationships: never[] };
      trip_timeline:     { Row: TripTimelineRow;    Insert: TripTimelineInsert;    Update: Partial<TripTimelineInsert>; Relationships: never[] };
      documents:         { Row: DocumentRow;        Insert: DocumentInsert;        Update: DocumentUpdate;        Relationships: never[] };
    };
    Views: {
      [_ in never]: never;
    };
    Functions: {
      get_org_stats: {
        Args:    { p_org_id: string };
        Returns: { trip_count: number; lead_count: number; customer_count: number; total_revenue: number; total_collected: number };
      };
      auth_org_id: {
        Args:    Record<string, never>;
        Returns: string;
      };
    };
    Enums: {
      user_role:         UserRole;
      trip_status:       TripStatus;
      lead_status:       LeadStatus;
      lead_priority:     LeadPriority;
      booking_type:      BookingType;
      booking_status:    BookingStatus;
      payment_status:    PaymentStatus;
      task_priority:     TaskPriority;
      task_status:       TaskStatus;
      document_category: DocumentCategory;
    };
    CompositeTypes: {
      [_ in never]: never;
    };
  };
}

